import sys

def solve():
    t_str = sys.stdin.readline()
    if not t_str:
        return
    t = int(t_str)

    for _ in range(t):
        line = sys.stdin.readline()
        while line and not line.strip():
            line = sys.stdin.readline()
        if not line:
            break
        n, k = map(int, line.split())

        current_guess = 0
        found = False

        for _ in range(n):
            print(current_guess)
            sys.stdout.flush()

            resp = sys.stdin.readline()
            while resp and not resp.strip():
                resp = sys.stdin.readline()
            if not resp:
                break

            r = int(resp.strip())

            if r == 1:
                found = True
                break
            elif r == -1:
                return
            else:
                current_guess += 1

        if not found:
            return

if __name__ == "__main__":
    solve()
